<script>
	// toolSearch.js is only needed once the user actually focuses a search field, not on every page
	// that happens to render a .toolSelectSearch block -- deferred like tippy/popper/sortable below.
	pdf24.requireToolSearch = function(callback) {
		return utilz.requireScript({
			loadCheck: function() {
				return window.pdf24 && pdf24.toolSearch;
			},
			callback: callback,
			script: {
				id: 'toolSearchScript',
				src: '/static/js/toolSearch.js?v=6ac63c12'
			}
		});
	};

	// Shared across every .toolSelectSearch instance on the page (home, bottomToolSelect, and the
	// burger-cloned topToolSelect), so the sitemap is only fetched once no matter how many search
	// boxes exist.
	pdf24.loadToolSelectSearchPages = function() {
		if(!pdf24.toolSelectSearchPagesPromise) {
			pdf24.toolSelectSearchPagesPromise = $.getJSON('/en/tool-search.json').then(function(data) {
				pdf24.toolSelectSearchPages = data.pages || [];
				return pdf24.toolSelectSearchPages;
			});
			// allow a retry on the next focus/search instead of caching the failure
			pdf24.toolSelectSearchPagesPromise.fail(function() {
				pdf24.toolSelectSearchPagesPromise = null;
			});
		}
		return pdf24.toolSelectSearchPagesPromise;
	};

	// Wires one .toolSelectSearch instance up. Called on page load for the instances rendered by the
	// server, and again from the topToolSelectInitialized hook (see common.js toggleTopToolSelect())
	// for the burger-cloned copy: jQuery's clone(true, true) only carries over jQuery-bound events,
	// not the addEventListener calls toolSearch.attach() makes, and even if it did, the handlers
	// would still close over the original instance's DOM nodes instead of the clone's -- so the
	// clone needs its own fresh attach() call against its own elements.
	pdf24.initToolSelectSearch = function(el) {
		// a plain property, not jQuery .data(): clone(true, true) copies the jQuery data cache, so a
		// .data() flag would make the clone look already-initialized and skip wiring it up entirely
		if(el.toolSelectSearchInit) {
			return;
		}
		el.toolSelectSearchInit = true;

		var searchBlock = $(el);
		var resultBox = searchBlock.find('.toolSelectSearchResults .items');
		var noItemsFound = searchBlock.find('.toolSelectSearchResults .noItemsFound');
		var status = searchBlock.find('.toolSelectSearchStatus');
		var searchInput = searchBlock.find('input[name="search"]')[0];
		var trackContext = searchBlock.closest('#topToolSelect').length ? 'Top'
			: (searchBlock.closest('#homeToolSelectBlock').length ? 'Home'
			: (searchBlock.closest('#bottomToolSelect').length ? 'Bottom' : 'AllTools'));
		var trackTimeout = null;

		var renderResult = function(item, term) {
			var a = document.createElement('a');
			a.className = 'toolLink ' + item.id;
			a.href = item.url;
			a.title = item.info;
			a.setAttribute('data-tool', item.id);

			var icon = document.createElement('div');
			icon.className = 'icon';
			icon.setAttribute('data-lazy-bg-src', item.icon);
			a.appendChild(icon);

			var labelEl = document.createElement('div');
			labelEl.className = 'label';
			// .label ist ein Flex-Container: ohne den Wrapper wuerde das <mark> den Text in
			// mehrere Flex-Items zerlegen und den Umbruch zerstoeren
			labelEl.innerHTML = '<span class="labelText">' + pdf24.toolSearch.highlight(item.label, term) + '</span>';
			a.appendChild(labelEl);

			a.addEventListener('click', function() {
				pdf24.trackPageEvent('UI', trackContext + 'ToolSearchClick', term + ' → ' + item.id);
			});

			return a;
		};

		// preload as soon as the user is about to search, the request is shared with buildIndex()
		searchInput.addEventListener('focus', pdf24.loadToolSelectSearchPages);

		var wired = false;
		var wireSearch = function() {
			if(wired) {
				return;
			}
			wired = true;

			var handle = pdf24.toolSearch.attach(searchInput, {
				buildIndex: function() {
					if(pdf24.toolSelectSearchPages) {
						return pdf24.toolSearch.createIndexFromData(pdf24.toolSelectSearchPages);
					}
					// first search: load the sitemap, then drop the empty index and run the search again
					pdf24.loadToolSelectSearchPages().done(function() {
						handle.rebuild();
						searchInput.dispatchEvent(new Event('input'));
					}).fail(function() {
						// drop the cached empty index, otherwise buildIndex never runs again to retry
						handle.rebuild();
					});
					return [];
				},
				onResults: function(results, term) {
					if(!pdf24.toolSelectSearchPages) {
						return;
					}
					resultBox.empty();

					results.forEach(function(result) {
						resultBox.append(renderResult(result.data, term));
					});

					noItemsFound.toggleClass('hidden', results.length > 0);
					searchBlock.addClass('active').toggleClass('noResults', results.length === 0);
					status.text(results.length);
					utilz.lazyLoad(resultBox.find('.toolLink .icon'));
					pdf24.tippyTitles(resultBox);

					trackTimeout && clearTimeout(trackTimeout);
					trackTimeout = setTimeout(function() {
						pdf24.trackPageEvent('UI', trackContext + 'ToolSearchUsage/en/' + results.length, term);
					}, 1000);
				},
				onReset: function() {
					resultBox.empty();
					noItemsFound.addClass('hidden');
					searchBlock.removeClass('active noResults');
					status.text('');
				},
				onEnter: function() {
					var first = resultBox.find('.toolLink')[0];
					if(first) {
						first.click();
					}
				}
			});

			// catch anything already typed while toolSearch.js was still loading
			searchInput.dispatchEvent(new Event('input'));
		};

		searchInput.addEventListener('focus', function() {
			pdf24.requireToolSearch(wireSearch);
		});
	};

	$(function() {
		$('.toolSelectSearch').each(function() {
			pdf24.initToolSelectSearch(this);
		});
	});

	utilz.actions.add('topToolSelectInitialized', function(toolSelectNode) {
		toolSelectNode.filter('.toolSelectSearch').add(toolSelectNode.find('.toolSelectSearch')).each(function() {
			pdf24.initToolSelectSearch(this);
		});
	});
</script>
<script>
	(function() {
		var favorites = utilz.localStorage.getItemObject('toolFavorites') || {};
		var updateClass = function(tid, e) {
			e = e || $('.toolSelect .toolLink.' + tid);
			e.find('.favstar i').attr('class', favorites[tid] ? 'icon-star' : 'icon-star-empty');
			e.toggleClass('favorite', favorites[tid] ? true : false);
		};
		$('.toolSelect').addClass('hasFavorites');
		$('.toolSelect .toolLink').each(function(i, e) {
			e = $(e);
			var toolId = e.data('tool');
			if(!toolId) {
				return;
			}

			var elem = $('<div class="favstar" title="Toggle favorite status"><i class="icon-star-empty"/></div>');
			elem.addClass(toolId);
			elem.click(function(e) {
				e.preventDefault();
				e.stopPropagation();
				favorites[toolId] = favorites[toolId] ? false : true;
				utilz.localStorage.setItemObject('toolFavorites', favorites);
				updateClass(toolId);
				pdf24.trackPageEvent('UI', 'ToggleToolFavorite', toolId);
				return false;
			});
			e.append(elem);
			updateClass(toolId, e);
		});
	})();
</script>

